<?php declare(strict_types=1); ?>
<section class="account-portal-card"><p class="eyebrow"><?=$e($copy['account'])?></p><?php if($data['saved']):?><h1><?=$e($data['reactivation']?'Cuenta reactivada':$copy['password_saved'])?></h1><p>Ya puedes entrar con tu correo y la nueva contraseña.</p><p><a class="pill" href="/negocios/acceso/"><?=$e($copy['login'])?></a></p><?php else:?><h1><?=$e($data['valid']?($data['reactivation']?'Reactiva tu cuenta':'Crea o cambia tu contraseña'):'Enlace vencido o no válido')?></h1><?php if($data['error']):?><p class="notice" role="alert"><?=$e($data['error'])?></p><?php endif ?><?php if($data['valid']):?><p>El enlace es de un solo uso y vence en 24 horas. Elige una contraseña nueva.</p><form method="post" class="registration-form"><input type="hidden" name="csrf" value="<?=$e($data['csrf'])?>"><input type="hidden" name="token" value="<?=$e($data['token'])?>"><?php if($data['reactivation']):?><input type="hidden" name="reactivacion" value="1"><label class="registration-consent"><input type="checkbox" name="confirm_reactivation" value="1" required><span>Quiero reactivar mi cuenta y conservar sus datos asociados.</span></label><?php endif ?><label><?=$e($copy['new_password'])?><input type="password" name="password" minlength="12" maxlength="200" autocomplete="new-password" required><small><?=$e($copy['password_help'])?></small></label><label><?=$e($copy['password_confirm'])?><input type="password" name="password_confirm" minlength="12" maxlength="200" autocomplete="new-password" required></label><button class="pill" type="submit"><?=$e($data['reactivation']?'Reactivar cuenta':$copy['password_submit'])?></button></form><?php else:?><p>Solicita al equipo un enlace nuevo. Por seguridad, no compartas este enlace con otras personas.</p><p><a href="/negocios/acceso/"><?=$e($copy['login_back'])?></a></p><?php endif ?><?php endif ?></section>
